+// Escapes quotes and backslashes so a node name can sit inside a quoted expression string,
+// e.g. `Bob's` -> `Bob\'s` in `$('Bob\'s')`. The escaped form is valid in both '' and "" strings.
+function escapeNameForExpression(nodeName: string) {
+	return nodeName.replace(/[\\'"]/g, (char) => `\\${char}`);
+}
+
+// Builds a regex source matching `nodeName` either raw or with its quotes/backslashes escaped,
+// since expressions may contain the name in either form.
+function nodeNameToRegexSource(nodeName: string) {
+	return [...nodeName]
+		.map((char) => {
+			if (char === '\\') return String.raw`\\{1,2}`;
+			if (char === "'" || char === '"') return String.raw`\\?${char}`;
+			return backslashEscape(char);
+		})
+		.join('');
+}
